ALTER TABLE "copy_live_execution_evidence" ADD COLUMN "settlement_proof" jsonb;--> statement-breakpoint
ALTER TABLE "copy_live_execution_evidence" ADD COLUMN "settlement_proof_digest" text;--> statement-breakpoint
ALTER TABLE "copy_live_execution_evidence" ADD CONSTRAINT "copy_live_evidence_settlement_proof_check" CHECK (("copy_live_execution_evidence"."settlement_proof" is null and "copy_live_execution_evidence"."settlement_proof_digest" is null) or ("copy_live_execution_evidence"."settlement_proof" is not null and "copy_live_execution_evidence"."settlement_proof_digest" is not null and jsonb_typeof("copy_live_execution_evidence"."settlement_proof") = 'object' and "copy_live_execution_evidence"."settlement_proof_digest" ~ '^[0-9a-f]{64}$' and "copy_live_execution_evidence"."settlement_certificate" is not null and "copy_live_execution_evidence"."settlement_digest" is not null));